namespace Fanex.BetList.Core.UnitTest.Builder.ChoiceBuilder
{
    using Fanex.BetList.Core.Builder.ChoiceBuilder;
    using Fanex.BetList.Core.UnitTest.Templates;
    using Fanex.BetList.Core.UnitTest.Ultils.Enums;
    using NUnit.Framework;

    public class Choice26Test
    {
        private ChoiceCreator _choiceCreator;

        [SetUp]
        public void Setup()
        {
            _choiceCreator = new ChoiceCreator(new Choice26(), BetTypes.Both_One_Neither);
        }

        [Test]
        public void BetTeamOfTicketIsB_ShowBetTeamIsBoth()
        {
            // Arrange
            _choiceCreator.Ticket.BetTeam = "b";

            // Act
            string actualValue = _choiceCreator.GetFirstChildInnerHtml(ChoiceXPath.BetTeam);

            // Assert
            string expected = ChoiceTemplate.Both;
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void BetTeamOfTicketIsO_ShowBetTeamIsOne()
        {
            // Arrange
            _choiceCreator.Ticket.BetTeam = "o";

            // Act
            string actualValue = _choiceCreator.GetFirstChildInnerHtml(ChoiceXPath.BetTeam);

            // Assert
            string expected = ChoiceTemplate.One;
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void BetTeamOfTicketIsN_ShowBetTeamIsNoGoal()
        {
            // Arrange
            _choiceCreator.Ticket.BetTeam = "n";

            // Act
            string actualValue = _choiceCreator.GetFirstChildInnerHtml(ChoiceXPath.BetTeam);

            // Assert
            string expected = ChoiceTemplate.NoGoal;
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void BetTeamOfTicketIsEmpty_VisibleSpanHandicap()
        {
            // Arrange
            _choiceCreator.Ticket.BetTeam = string.Empty;

            // Act
            string actualValue = _choiceCreator.GetFirstChildInnerHtml(ChoiceXPath.BetTeamHandicap);

            // Assert
            string expected = " ";
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void BetTeamOfTicketIs1_ShowBetTeamClassNameIsFavorite()
        {
            // Arrange
            _choiceCreator.Ticket.BetTeam = "1";

            // Act
            string actualValue = _choiceCreator.GetHtmlClassValue(ChoiceXPath.BetTeam);

            // Assert
            string expected = ChoiceTemplate.BLFavorite;
            Assert.AreEqual(expected, actualValue);
        }
       
    }
}